import{_ as s,D as i,c as n,j as a,a as e,I as h,a4 as o,o as r}from"./chunks/framework.CRCV4hx_.js";const F=JSON.parse('{"title":"Payment Gateways","description":"","frontmatter":{},"headers":[],"relativePath":"payment-gateways.md","filePath":"payment-gateways.md"}'),l={name:"payment-gateways.md"},p={id:"payment-gateways",tabindex:"-1"},d=a("a",{class:"header-anchor",href:"#payment-gateways","aria-label":'Permalink to "Payment Gateways <Badge type="tip" text="NEW" />"'},"​",-1),c=o(`<p>Statamic Resrv processes payments through one or more <strong>payment gateways</strong>. Out of the box it ships with two: <a href="./stripe">Stripe</a> for card payments and a bundled <strong>Offline</strong> gateway for bank transfer or pay-at-premises bookings. In v6 you can also configure <strong>multiple gateways at once</strong> and let the customer choose at checkout, apply a per-gateway surcharge, and restrict gateways to a specific order-value range.</p><p>This page covers how gateways are configured and how they behave. For the gateways themselves see <a href="./stripe">Stripe</a>, <a href="./mollie">Mollie</a>, and the <a href="./custom-payment-gateway">Custom payment gateway</a> guide. For where gateways appear in the booking flow, see <a href="./checkout">Checkout</a>.</p><h2 id="configuring-gateways" tabindex="-1">Configuring gateways <a class="header-anchor" href="#configuring-gateways" aria-label="Permalink to &quot;Configuring gateways&quot;">​</a></h2><p>Gateways are a <strong>developer setting</strong>, configured in <code>config/resrv-config.php</code>, not in the Control Panel. The <code>payment_gateways</code> key is an array keyed by a machine name, with one entry per gateway:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// config/resrv-config.php</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;payment_gateways&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;stripe&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;class&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">         =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\Reach\\StatamicResrv\\Http\\Payment\\StripePaymentGateway</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;label&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">         =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Credit Card&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;surcharge&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">     =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;type&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;percent&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;amount&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;amount_limits&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;min&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;max&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ],</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;offline&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;class&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\Reach\\StatamicResrv\\Http\\Payment\\OfflinePaymentGateway</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;label&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Bank Transfer / Pay at Premises&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span></code></pre></div><p>Each entry accepts the following keys:</p><table tabindex="0"><thead><tr><th>Key</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>class</code></td><td>Yes</td><td>FQCN</td><td>The gateway class. Must implement <code>PaymentInterface</code> or the app throws at boot.</td></tr><tr><td><code>label</code></td><td>No</td><td>String</td><td>The label shown in the checkout picker. Falls back to the gateway&#39;s own <code>label()</code> when omitted.</td></tr><tr><td><code>surcharge</code></td><td>No</td><td>Array</td><td>A per-gateway surcharge added on top of the payment. See <a href="#surcharges">Surcharges</a>.</td></tr><tr><td><code>amount_limits</code></td><td>No</td><td>Array</td><td>Restricts the gateway to an order-value range. See <a href="#amount-limits">Amount limits</a>.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The array <strong>key</strong> (e.g. <code>stripe</code>, <code>offline</code>) is the gateway&#39;s config name. It is used in the per-gateway webhook URL and the <code>resrv_gateway</code> redirect parameter, so keep it lowercase with no spaces.</p></div><h3 id="the-default-gateway" tabindex="-1">The default gateway <a class="header-anchor" href="#the-default-gateway" aria-label="Permalink to &quot;The default gateway&quot;">​</a></h3><p>When <code>payment_gateways</code> is a non-empty array, <strong>the first entry is the default gateway</strong>. It is used as the fallback for any reservation that has no gateway recorded yet (for example, older reservations created before you added the config).</p><h3 id="legacy-single-gateway-fallback" tabindex="-1">Legacy single-gateway fallback <a class="header-anchor" href="#legacy-single-gateway-fallback" aria-label="Permalink to &quot;Legacy single-gateway fallback&quot;">​</a></h3><p>If you leave <code>payment_gateways</code> empty, Resrv falls back to the legacy singular <code>payment_gateway</code> key, which defaults to the Stripe gateway:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// config/resrv-config.php</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;payment_gateway&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\Reach\\StatamicResrv\\Http\\Payment\\StripePaymentGateway</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span></code></pre></div><p>Existing single-gateway sites need <strong>no changes</strong>. Stripe keeps working exactly as before, the checkout never shows a picker, and the bare webhook URL keeps resolving. Only define <code>payment_gateways</code> when you want more than one gateway or want to apply surcharges and amount limits.</p><h2 id="the-offline-gateway" tabindex="-1">The Offline gateway <a class="header-anchor" href="#the-offline-gateway" aria-label="Permalink to &quot;The Offline gateway&quot;">​</a></h2><p>The bundled <code>OfflinePaymentGateway</code> (<code>offline</code>) is for bookings that are paid outside the site: bank transfer, pay-at-premises, or pay-later. It talks to no external provider.</p><p>Instead of an inline payment form, the offline payment step shows a description, the amount due, and a <strong>Confirm reservation</strong> button. Pressing it confirms the reservation immediately on the server and fires the <code>ReservationConfirmed</code> event, so the <strong>confirmation email is sent right away</strong>, with no webhook involved. The customer then lands on the checkout-complete page with a <code>pending</code> status, signalling the booking is held and awaiting payment.</p><p>Add it to your <code>payment_gateways</code> array like any other gateway:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;offline&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;class&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\Reach\\StatamicResrv\\Http\\Payment\\OfflinePaymentGateway</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;label&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Bank Transfer&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The offline description, amount label, and button text are translation keys (<code>offlinePaymentDescription</code>, <code>offlinePaymentAmount</code>, <code>confirmReservation</code>, and others). You can override all of them, see <a href="./languages">Languages</a>.</p></div><h2 id="surcharges" tabindex="-1">Surcharges <a class="header-anchor" href="#surcharges" aria-label="Permalink to &quot;Surcharges&quot;">​</a></h2><p>A surcharge adds an extra amount on top of the payment when a customer picks a particular gateway, useful for passing on card-processing fees. Configure it per gateway with a <code>type</code> and an <code>amount</code>:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 4% on top of the amount payable now</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;surcharge&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;type&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;percent&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;amount&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// A flat 2.50 in your currency&#39;s major units</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;surcharge&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;type&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;fixed&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;amount&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Type</th><th><code>amount</code> means</th><th>Example</th></tr></thead><tbody><tr><td><code>percent</code></td><td>A percentage of the payment</td><td><code>4</code> adds 4%</td></tr><tr><td><code>fixed</code></td><td>A flat amount in major currency units</td><td><code>2.50</code> adds 2.50</td></tr></tbody></table><p>Any other <code>type</code> throws an error when that gateway&#39;s surcharge is calculated at checkout.</p><p>How it behaves:</p><ul><li>The surcharge is calculated from the reservation&#39;s <strong>payment</strong> (the amount payable now), <strong>before</strong> the surcharge is added.</li><li>The gateway is charged the <strong>full total</strong> (<code>payment + surcharge</code>). The reservation&#39;s <code>payment</code> value stays the booking amount: the surcharge is stored separately in the <code>payment_surcharge</code> column and surfaced in the totals.</li><li>The checkout picker shows the surcharge next to the gateway label, e.g. <code>(+4% surcharge)</code> or <code>(+ €2.50 surcharge)</code>, so the customer sees the cost before choosing.</li></ul><h2 id="amount-limits" tabindex="-1">Amount limits <a class="header-anchor" href="#amount-limits" aria-label="Permalink to &quot;Amount limits&quot;">​</a></h2><p>Amount limits restrict a gateway to a specific order-value range. Set an inclusive <code>min</code>, <code>max</code>, or both:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;amount_limits&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;min&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;max&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;amount_limits&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;min&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// no upper bound</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;amount_limits&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;max&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// no lower bound</span></span></code></pre></div><p>How it behaves:</p><ul><li><code>min</code> and <code>max</code> are <strong>inclusive</strong>: the gateway is offered when <code>payment &gt;= min</code> and <code>payment &lt;= max</code>.</li><li>The limit is compared against the reservation&#39;s <strong>payment</strong> (the amount payable now), <strong>before</strong> any surcharge is applied.</li><li>A gateway whose limits the payment falls outside of is <strong>hidden from the picker</strong> entirely.</li></ul><p>Edge cases worth knowing:</p><ul><li><strong>No gateway available</strong>: if <em>every</em> gateway is filtered out for the current amount, checkout shows the <code>noGatewayAvailableForAmount</code> error and cannot advance. Make sure your ranges always cover every possible total.</li><li><strong>Single survivor</strong>: if exactly one gateway passes the filter, it is auto-selected and no picker is shown.</li><li><strong>Free reservations</strong>: when <code>payment</code> is <code>0</code>, the payment step is skipped entirely and amount limits are never evaluated. See <a href="./checkout">Skipping payment</a>.</li><li>A coupon applied after a gateway is selected does not retroactively invalidate an in-flight payment: limits gate the <em>selection</em>, not processing.</li></ul><div class="warning custom-block"><p class="custom-block-title">BOOT-TIME VALIDATION</p><p><code>amount_limits</code> must be an array, every value must be a parseable amount, only <code>min</code> and <code>max</code> keys are allowed, and <code>min</code> may not be greater than <code>max</code>. Breaking any of these throws an error when the app boots, so you&#39;ll catch configuration mistakes immediately.</p></div><h2 id="the-checkout-gateway-picker" tabindex="-1">The checkout gateway picker <a class="header-anchor" href="#the-checkout-gateway-picker" aria-label="Permalink to &quot;The checkout gateway picker&quot;">​</a></h2><p>When more than one gateway survives amount filtering, the customer reaches a <strong>gateway picker</strong> at the payment step. It lists each available gateway by label, with any surcharge shown alongside, under a &quot;Select payment method&quot; heading.</p><ul><li>Picking a gateway initialises that gateway&#39;s payment: an inline form (Stripe), the offline confirmation screen, or a redirect to the provider.</li><li>If only one gateway is available it is <strong>auto-selected</strong> and the picker is skipped.</li><li>If the booking total is zero, the payment step is skipped altogether.</li></ul><p>See <a href="./checkout">Checkout</a> for the full step-by-step flow and how to customise the checkout views.</p><h2 id="webhook-routes" tabindex="-1">Webhook routes <a class="header-anchor" href="#webhook-routes" aria-label="Permalink to &quot;Webhook routes&quot;">​</a></h2><p>Each gateway has its own webhook URL so providers can notify Resrv independently:</p><table tabindex="0"><thead><tr><th>Route</th><th>Resolves to</th></tr></thead><tbody><tr><td><code>/resrv/api/webhook/{gateway}</code></td><td>The gateway whose config key is <code>{gateway}</code></td></tr><tr><td><code>/resrv/api/webhook</code></td><td>The default gateway (single-gateway sites only)</td></tr></tbody></table><p>Both <code>GET</code> and <code>POST</code> are available on each route, and all are exempt from CSRF protection.</p><div class="warning custom-block"><p class="custom-block-title">MULTIPLE GATEWAYS REQUIRE THE PER-GATEWAY URL</p><p>As soon as you configure <code>payment_gateways</code> with more than one gateway, the <strong>bare</strong> <code>/resrv/api/webhook</code> URL returns a <strong>404</strong>: Resrv refuses to guess which gateway a notification belongs to. You must point each provider at its specific <code>/resrv/api/webhook/{gateway}</code> URL (for example <code>/resrv/api/webhook/stripe</code>).</p><p>Single-gateway sites can keep using the bare URL.</p></div><p>See the <a href="./stripe">Stripe</a> page for setting up the Stripe webhook and its signing secret.</p><h2 id="redirect-vs-inline-gateways" tabindex="-1">Redirect vs inline gateways <a class="header-anchor" href="#redirect-vs-inline-gateways" aria-label="Permalink to &quot;Redirect vs inline gateways&quot;">​</a></h2><p>A gateway is either <strong>inline</strong> or <strong>redirect</strong>:</p><ul><li><strong>Inline</strong> gateways (like Stripe and the offline gateway) render their payment UI directly on the checkout page. The customer never leaves your site.</li><li><strong>Redirect</strong> gateways send the customer to the provider&#39;s hosted payment page. On the way out, Resrv appends a <code>resrv_gateway=&lt;config-key&gt;</code> query parameter to the redirect URL.</li></ul><p>When the customer returns, your checkout-complete page (the one rendering the <code>{{ resrv_checkout_redirect }}</code> tag) resolves which gateway handled the payment, preferring the reservation&#39;s stored gateway, then the <code>resrv_gateway</code> query parameter, then the default. It then reports a <code>success</code>, <code>failed</code>, or <code>pending</code> status. See <a href="./checkout">Checkout</a> for the redirect page details.</p><h2 id="cancelling-abandoned-payments" tabindex="-1">Cancelling abandoned payments <a class="header-anchor" href="#cancelling-abandoned-payments" aria-label="Permalink to &quot;Cancelling abandoned payments&quot;">​</a></h2><p>When a customer backs out of payment, switches to a different gateway at the picker, or reopens an expired checkout, Resrv cancels the abandoned payment intent at the provider so no stale authorisation lingers. It clears the recorded payment id and gateway first, then asks the gateway to cancel the old intent; any error from the provider during cancellation is logged and ignored so it can never block checkout.</p><p>The offline gateway has nothing to cancel, so its cancellation is a no-op. If you build your own gateway, this behaviour is part of the <code>PaymentInterface</code> you implement, see the <a href="./custom-payment-gateway">Custom payment gateway</a> guide.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./stripe">Stripe</a>: set up the default card gateway.</li><li><a href="./mollie">Mollie</a>: a maintained redirect gateway add-on.</li><li><a href="./custom-payment-gateway">Custom payment gateway</a>: build your own gateway against <code>PaymentInterface</code>.</li><li><a href="./checkout">Checkout</a>: where gateways appear in the booking flow.</li><li><a href="./configuration">Configuration</a>: the rest of the developer config keys.</li><li><a href="./languages">Languages</a>: translate payment-related labels and messages.</li></ul>`,54);function g(k,y,u,m,f,w){const t=i("Badge");return r(),n("div",null,[a("h1",p,[e("Payment Gateways "),h(t,{type:"tip",text:"NEW"}),e(),d]),c])}const b=s(l,[["render",g]]);export{F as __pageData,b as default};
